{
  "checks": [
    {
      "problem": "对比度、色差检测明细表只按位置名或颜色对列行、不带问题编号，位置写法还与问题清单不一致，读者无法把某一行数值对到某条问题",
      "A": "解决",
      "B": "没解决"
    },
    {
      "problem": "问题清单的「影响」列用色觉类型缩写、表头被页面边缘截断，与「按色盲类型」里的全称对不上",
      "A": "解决",
      "B": "部分解决"
    },
    {
      "problem": "修复动作表里有些改动行匹配不到问题编号，读者无法判断这些改动覆盖了哪条问题",
      "A": "解决",
      "B": "解决"
    }
  ],
  "worse": [
    {
      "version": "B",
      "where": "对比度表",
      "why": "整列问题编号被去掉，10 行里哪几行属于 P3、P4、P5 只能靠位置文字自己配；位置又简化成「辅助文字」「坐标轴文字」「卡片说明」「成功标签文字」，读者要来回对照明细才能确认，A 版直接看编号即可。"
    },
    {
      "version": "B",
      "where": "混淆色表",
      "why": "同样没有编号列，4 行色差数据里哪两行是问题清单里的 P1、哪两行不在清单里完全看不出来；A 版用编号列加「空编号为未列入问题清单的检查项」的脚注把这件事说清。"
    },
    {
      "version": "B",
      "where": "明细表的「影响」列",
      "why": "列头「影响(红/绿/蓝)」超出页面右边缘被截断，单元格里仍是「红、绿」「红、绿、蓝」缩写，读者无法就地确认对应的是红色盲/绿色盲/蓝色盲，得回到上面的「按色盲类型」去对；A 版该列直接写「红色盲、绿色盲」全称。"
    },
    {
      "version": "A",
      "where": "混淆色表",
      "why": "表中的红色数值（7.8、3.9、8.7、11.2、11.6）没有说明含义，读者要自己回忆副标题「小于 12 视为难以区分」才能判断；B 版在表下直接注明「红色为该色觉类型下难以区分」。"
    }
  ],
  "better": "A",
  "reason": "A 版给「混淆色」「对比度」两张检测表都加了问题编号列并把位置写法与问题清单统一，明细的「影响」列写全称、修复动作每行都有编号，读者不必再靠文字来回配对；B 版这两张表都去掉了编号，影响列仍是缩写且表头被页面右边缘截断。",
  "next": [
    {
      "where": "对比度表（成功标签文字一行）",
      "task": "把「成功标签文字 2.27 不达标」对到某条问题",
      "why": "该行编号列是空的，而表下脚注写「空编号为未列入问题清单的检查项」，读者会以为它不属任何问题，但明细里 P5 的标题是「成功、警告标签白字对比度不足」，需要再回明细核对才能确认这一行就是 P5。"
    },
    {
      "where": "混淆色表",
      "task": "看懂标红的色差数值代表什么",
      "why": "表里只有副标题「CIEDE2000 色差，小于 12 视为难以区分」，没有说明红色数字是「该色觉类型下难以区分」，读者要逐个把红色数字和 12 比较才能确认。"
    },
    {
      "where": "修复动作表",
      "task": "确认 P1、P2、P6 这三条问题是否也有对应改动",
      "why": "表里只有 P3、P4、P5 四行颜色改动，没有说明该表只覆盖对比度类修复，读者要回到明细和「下一步」逐条比对，才能判断 P1、P2、P6 是结构性建议而非漏修。"
    }
  ]
}
